// js
// LPA ss.32, 57: sick leave past thirty paid working days carries no wage.
// LPA s.5: the fixed allowance is wage and goes with the days. proration_basis CALENDAR_DAYS: s.56(1) pays a month through its weekly holidays and s.68 counts it in days.
const terms = ctx.subject.employment.terms;
const coverage = ctx.run.salary_coverage;
const slots = ctx.entry.days.map((day) => day.date);
const whole = slots
	.filter((date, index) => slots.indexOf(date) === index && slots.filter((other) => other === date).length > 1)
	.toSorted();
const scheduled = get(ctx.subject.employer, 'payment_schedule.non_working_weekdays', [0, 6]);
const week = Number(get(ctx.subject.employment.terms, 'normal_days_per_week', 7 - scheduled.length));
const off = week === 7 - scheduled.length ? scheduled : [0, 6, 5, 4, 3, 2, 1].slice(0, 7 - week);
const worksOn = (date) => {
	const day = ctx.work.days.find((row) => row.date === date);
	return day == null ? !off.includes(weekday(date)) : ['WORK', 'ABS'].includes(get(day, 'day_type', 'WORK'));
};
let rest = 0;
for (let index = 1; index < whole.length; index += 1) {
	let between = [];
	for (let step = 1; step < calendar_distance_days(whole[index - 1], whole[index]); step += 1)
		between = [...between, add_days(whole[index - 1], step)];
	if (between.length > 0 && !between.some(worksOn)) rest += between.length;
}
const reversal = ctx.entry.is_reversal === true;
const back = add_days(coverage.from, -1);
const halves = get(ctx.subject.employer, 'payment_schedule.frequency', '') === 'SEMI_MONTHLY';
const from = !reversal ? coverage.from : halves && Number(String(back).slice(8, 10)) > 15 ? add_days(month_start(back), 15) : String(month_start(back));
const to = reversal ? back : coverage.to;
const days = calendar_distance_days(from, to) + 1;
const lost = Math.min(ctx.entry.quantity + rest, days);
const calendar = calendar_distance_days(month_start(from), month_end(from)) + 1;
const allowance = (Number(get(terms, 'allowances.FIXED_ALLOWANCE.amount', 0)) * lost) / calendar;
// a day or hour rate pays the working day; only a salary follows the calendar
if (['DAILY', 'HOURLY'].includes(get(terms, 'rate.unit', 'MONTHLY'))) return ctx.day_rate * ctx.entry.quantity + allowance;
return (Number(get(terms, 'rate.amount', 0)) * lost) / days + allowance;

